    , 
    /**
     * The refusal when `asking` is `Refused`.
     */
    var `refuse`: RefuseReason?
    , 
    /**
     * Where the phone is, for the reply.
     */
    var `place`: Place
    , 
    /**
     * Level 2 and 3: the number match comes first.
     */
    var `needsNumber`: kotlin.Boolean
    , 
    /**
