data class WordEntry (
    /**
     * Letters `a` to `z` that keep the prefix valid.
     */
    var `nextLetters`: List<kotlin.String>
    , 
    /**
     * The only word starting with the prefix, when there is one.
     */
    var `completed`: kotlin.String?
    , 
    /**
     * The prefix is itself a whole word (for example `act`, which also starts `action`).
     */
    var `exact`: kotlin.Boolean
    , 
    /**
     * No BIP39 word starts with the prefix.
     */
    var `invalid`: kotlin.Boolean
    
){
    

    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeWordEntry: FfiConverterRustBuffer<WordEntry> {
    override fun read(buf: ByteBuffer): WordEntry {
        return WordEntry(
            FfiConverterSequenceString.read(buf),
            FfiConverterOptionalString.read(buf),
            FfiConverterBoolean.read(buf),
            FfiConverterBoolean.read(buf),
        )
    }

    override fun allocationSize(value: WordEntry) = (
            FfiConverterSequenceString.allocationSize(value.`nextLetters`) +
            FfiConverterOptionalString.allocationSize(value.`completed`) +
            FfiConverterBoolean.allocationSize(value.`exact`) +
            FfiConverterBoolean.allocationSize(value.`invalid`)
    )

    override fun write(value: WordEntry, buf: ByteBuffer) {
            FfiConverterSequenceString.write(value.`nextLetters`, buf)
            FfiConverterOptionalString.write(value.`completed`, buf)
            FfiConverterBoolean.write(value.`exact`, buf)
            FfiConverterBoolean.write(value.`invalid`, buf)
    }
}



