/**
 * Failures of the app rules and the local database.
 */
sealed class AppException: kotlin.Exception() {
    
    /**
     * The local database failed.
     */
    class Storage(
        
        /**
         * What failed (no secrets).
         */
        val `msg`: kotlin.String
        ) : AppException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    
    /**
     * State bytes that do not decode.
     */
    class Decode(
        ) : AppException() {
        override val message
            get() = ""
    }
    
    /**
     * State written by a newer app.
     */
    class NewerVersion(
        ) : AppException() {
        override val message
            get() = ""
    }
    
    /**
     * No such record.
     */
    class NotFound(
        ) : AppException() {
        override val message
            get() = ""
    }
    
    /**
     * A value outside its allowed range.
     */
    class Invalid(
        
        /**
         * Which value.
         */
        val `msg`: kotlin.String
        ) : AppException() {
        override val message
            get() = "msg=${ `msg` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<AppException> {
        override fun lift(error_buf: RustBuffer.ByValue): AppException = FfiConverterTypeAppError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeAppError : FfiConverterRustBuffer<AppException> {
    override fun read(buf: ByteBuffer): AppException {
        

        return when(buf.getInt()) {
            1 -> AppException.Storage(
                FfiConverterString.read(buf),
                )
            2 -> AppException.Decode()
            3 -> AppException.NewerVersion()
            4 -> AppException.NotFound()
            5 -> AppException.Invalid(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: AppException): ULong {
        return when(value) {
            is AppException.Storage -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
            is AppException.Decode -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is AppException.NewerVersion -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is AppException.NotFound -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is AppException.Invalid -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`msg`)
            )
        }
    }

    override fun write(value: AppException, buf: ByteBuffer) {
        when(value) {
            is AppException.Storage -> {
                buf.putInt(1)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
            is AppException.Decode -> {
                buf.putInt(2)
                Unit
            }
            is AppException.NewerVersion -> {
                buf.putInt(3)
                Unit
            }
            is AppException.NotFound -> {
                buf.putInt(4)
                Unit
            }
            is AppException.Invalid -> {
                buf.putInt(5)
                FfiConverterString.write(value.`msg`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



/**
 * How the phone answers.
 */

enum class Asking {
    
    /**
     * Answered with no tap (`automatic_decision`).
     */
    AUTOMATIC,
    /**
     * A notification with actions, or the approval card in the foreground.
     */
    ONE_TAP,
    /**
     * A notification that opens the app: levels 2 and 3, `old_words`, unknown kinds.
     */
    IN_APP,
    /**
     * `report`: answered with `seal_report_reply`, never shown.
     */
    SILENT,
    /**
     * Answered at once with `refuse` and no notification (`held`), or with a notice
     * (`not_near`, `no_biometrics`).
     */
    REFUSED,
    /**
     * A later part of an approved plan: answered with `seal_plan_keys_reply`.
     */
    PLAN_KEYS;

    


    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeAsking: FfiConverterRustBuffer<Asking> {
    override fun read(buf: ByteBuffer) = try {
        Asking.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: Asking) = 4UL

    override fun write(value: Asking, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}





/**
