                FfiConverterSequenceTypeMachineSeen.read(buf),
                )
            5 -> Event.RememberAnswer(
                FfiConverterTypeRememberedAnswer.read(buf),
                )
            6 -> Event.RemoveAnswer(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
