                )
            12 -> Event.AddReport(
                FfiConverterTypeHandbackReport.read(buf),
                )
            13 -> Event.MergeRemote(
                FfiConverterTypeState.read(buf),
                )
            14 -> Event.ForgetMachines
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: Event): ULong = when(value) {
        is Event.PairMachine -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeMachine.allocationSize(value.`machine`)
                + FfiConverterOptionalString.allocationSize(value.`replaces`)
            )
        }
        is Event.UnpairMachine -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`key`)
            )
        }
