                + FfiConverterString.allocationSize(value.`agent`)
                + FfiConverterString.allocationSize(value.`keyName`)
                + FfiConverterString.allocationSize(value.`repoId`)
            )
        }
        is Event.AddPlace -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeTrustedPlace.allocationSize(value.`place`)
            )
        }
        is Event.RenamePlace -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`id`)
                + FfiConverterString.allocationSize(value.`name`)
            )
        }
        is Event.RemovePlace -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`id`)
            )
        }
        is Event.SetWords -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeWordsInfo.allocationSize(value.`words`)
            )
        }
        is Event.SetSettings -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
