    }

    override fun allocationSize(value: LocalEvent): ULong = when(value) {
        is LocalEvent.SetDay -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeDayRecord.allocationSize(value.`day`)
            )
        }
        is LocalEvent.SetHold -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeHold.allocationSize(value.`hold`)
            )
        }
        is LocalEvent.ClearHold -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`machine`)
            )
        }
        is LocalEvent.PutPlan -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypePlanApprovalRecord.allocationSize(value.`plan`)
            )
        }
        is LocalEvent.PutDelayed -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeDelayedAction.allocationSize(value.`action`)
            )
        }
        is LocalEvent.RemoveDelayed -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`id`)
            )
        }
        is LocalEvent.SetDevice -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeDeviceInfo.allocationSize(value.`device`)
            )
        }
        is LocalEvent.SetOnboardingStep -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterUInt.allocationSize(value.`step`)
            )
        }
        is LocalEvent.AgentNoteShown -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is LocalEvent.SuppressCandidate -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`id`)
            )
        }
        is LocalEvent.SetLeave -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterUInt.allocationSize(value.`step`)
                + FfiConverterSequenceString.allocationSize(value.`skipped`)
            )
        }
        is LocalEvent.Synced -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterULong.allocationSize(value.`rev`)
                + FfiConverterBoolean.allocationSize(value.`uploaded`)
            )
        }
    }

    override fun write(value: LocalEvent, buf: ByteBuffer) {
        when(value) {
            is LocalEvent.SetDay -> {
                buf.putInt(1)
                FfiConverterTypeDayRecord.write(value.`day`, buf)
                Unit
            }
            is LocalEvent.SetHold -> {
                buf.putInt(2)
                FfiConverterTypeHold.write(value.`hold`, buf)
                Unit
            }
            is LocalEvent.ClearHold -> {
                buf.putInt(3)
                FfiConverterString.write(value.`machine`, buf)
                Unit
            }
            is LocalEvent.PutPlan -> {
                buf.putInt(4)
                FfiConverterTypePlanApprovalRecord.write(value.`plan`, buf)
                Unit
            }
            is LocalEvent.PutDelayed -> {
                buf.putInt(5)
                FfiConverterTypeDelayedAction.write(value.`action`, buf)
                Unit
            }
            is LocalEvent.RemoveDelayed -> {
                buf.putInt(6)
                FfiConverterString.write(value.`id`, buf)
                Unit
            }
            is LocalEvent.SetDevice -> {
                buf.putInt(7)
                FfiConverterTypeDeviceInfo.write(value.`device`, buf)
                Unit
            }
            is LocalEvent.SetOnboardingStep -> {
                buf.putInt(8)
                FfiConverterUInt.write(value.`step`, buf)
                Unit
            }
            is LocalEvent.AgentNoteShown -> {
                buf.putInt(9)
                Unit
            }
            is LocalEvent.SuppressCandidate -> {
                buf.putInt(10)
                FfiConverterString.write(value.`id`, buf)
                Unit
            }
            is LocalEvent.SetLeave -> {
                buf.putInt(11)
                FfiConverterUInt.write(value.`step`, buf)
                FfiConverterSequenceString.write(value.`skipped`, buf)
                Unit
            }
            is LocalEvent.Synced -> {
                buf.putInt(12)
                FfiConverterULong.write(value.`rev`, buf)
                FfiConverterBoolean.write(value.`uploaded`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}





/**
 * The buttons the card and the notification offer, in order.
 */

enum class ReplyOption {
    
    /**
     * "Allow for this session" (`Session`, or `Remember` when an agent's first use is merged).
     */
    ALLOW_SESSION,
    /**
     * "Allow" for `agent` (`Remember`) and `keys` (`Session`).
     */
    ALLOW,
    /**
     * "Allow once" (`Once`).
     */
    ALLOW_ONCE,
    /**
     * "Deny".
     */
    DENY,
    /**
     * Level 2 and 3: confirm with biometrics (and the number, plan, delay before it).
     */
    CONFIRM;

    


    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeReplyOption: FfiConverterRustBuffer<ReplyOption> {
    override fun read(buf: ByteBuffer) = try {
        ReplyOption.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: ReplyOption) = 4UL

    override fun write(value: ReplyOption, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}






